head.script:
scwin.screenId = "jldfil25112";

///////// 1. 변수 및 선언 영역 /////////

scwin.selFrm = undefined;


///////// 2. 초기화 영역 /////////

// 속성 EL 실현 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_attrReals
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_attrReals = async function () {
    const attrRealsList = [{ childId: "td_126", attr: "__html", fn: function () { return ([String(((1 === "1") ? "책임자" : "담당자"))].some(function (v) { return String(v == null ? '' : v).trim() !== ''; }) ? (String(((1 === "1") ? "책임자" : "담당자")) + "소재지<br/>회사 주소") : ''); } },
        { childId: "td_126_r1", attr: "__html", fn: function () { return ([String(((2 === "1") ? "책임자" : "담당자"))].some(function (v) { return String(v == null ? '' : v).trim() !== ''; }) ? (String(((2 === "1") ? "책임자" : "담당자")) + "소재지<br/>회사 주소") : ''); } },
        { childId: "td_126_r2", attr: "__html", fn: function () { return ([String(((3 === "1") ? "책임자" : "담당자"))].some(function (v) { return String(v == null ? '' : v).trim() !== ''; }) ? (String(((3 === "1") ? "책임자" : "담당자")) + "소재지<br/>회사 주소") : ''); } }];
    const root = (function () { try { const f = $c.win.getFrame(); return (f && f.render) ? f.render : null; } catch (e) { return null; } })();
    const hasText = function (t) { return /[가-힣A-Za-z0-9]/.test(String(t == null ? "" : t)); };
    let applied = 0;
    for (let i = 0; i < attrRealsList.length; i++) {
        const a = attrRealsList[i];
        const comp = $c.util.getComponent(a.childId);
        const el = (comp && comp.getID && root) ? root.querySelector("#" + comp.getID()) : null;
        if (!comp && !el) { console.warn("[sdd] 속성 실현 대상 부재: " + a.childId); continue; }
        let v;
        try { v = a.fn(); } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId + "." + a.attr }); continue; }
        if (a.attr === "style") {
            if (comp && typeof comp.setStyle === "function") {
                const decls = String(v).split(";");
                for (let di = 0; di < decls.length; di++) {
                    const kv = decls[di].split(":");
                    if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
                }
            } else if (el) { el.style.cssText = (el.style.cssText || "") + ";" + v; }
        } else if (a.attr === "label") {
            if (comp && typeof comp.setValue === "function") { comp.setValue(v); } else if (el) { el.textContent = v; }
        } else if (a.attr === "__value") {
            if (comp && typeof comp.setValue === "function") { comp.setValue(v); }
        } else if (a.attr === "__items") {
            if (comp && typeof comp.addItem === "function" && v && v.length) {
                let hasVal = false;
                for (let ii = 0; ii < v.length; ii++) { if (hasText(v[ii][0]) || hasText(v[ii][1])) { hasVal = true; break; } }
                if (hasVal) {
                    if (typeof comp.removeAll === "function") { comp.removeAll(); }
                    for (let ij = 0; ij < v.length; ij++) {
                        const lb = String(v[ij][1] || "");
                        comp.addItem(String(v[ij][0] || ""), hasText(lb) ? lb : "");
                    }
                }
            }
        } else if (a.attr === "class") {
            if (el) { el.className = v; }
        } else if (a.attr === "__html") {
            if (el && !el.querySelector('[class*="w2"], input, select, textarea, button')) { el.innerHTML = v; }
        } else if (el) {
            el.setAttribute(a.attr, v);
            if (a.attr === "src" && el.tagName === "IMG") { el.src = v; }
        }
        applied++;
    }
    return applied;
};

// 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_conds
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_conds = async function () {
    const binds = [{ id: "c_otherwise_46", fn: function(){ return (!((1==1) || (1==2))); } }, { id: "c_when_48_txt", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "spotIsuTrdMktTpCd" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("spotIsuTrdMktTpCd")) ==='2'); } }, { id: "c_otherwise_49", fn: function(){ return (!((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "spotIsuTrdMktTpCd" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("spotIsuTrdMktTpCd")) ==='2'))); } }, { id: "c_when_44_r1_txt", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "spotIsuTrdMktTpCd" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("spotIsuTrdMktTpCd")) ==='2'); } }, { id: "c_otherwise_45_r1", fn: function(){ return (!((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "spotIsuTrdMktTpCd" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("spotIsuTrdMktTpCd")) ==='2'))); } }, { id: "c_otherwise_46_r1", fn: function(){ return (!((2==1) || (2==2))); } }, { id: "c_when_48_r1_txt", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "spotIsuTrdMktTpCd" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("spotIsuTrdMktTpCd")) ==='2'); } }, { id: "c_otherwise_49_r1", fn: function(){ return (!((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "spotIsuTrdMktTpCd" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("spotIsuTrdMktTpCd")) ==='2'))); } }, { id: "c_otherwise_46_r2", fn: function(){ return (!((3==1) || (3==2))); } }, { id: "c_when_48_r2_txt", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "spotIsuTrdMktTpCd" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("spotIsuTrdMktTpCd")) ==='2'); } }, { id: "c_otherwise_49_r2", fn: function(){ return (!((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "spotIsuTrdMktTpCd" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("spotIsuTrdMktTpCd")) ==='2'))); } }];
    let applied = 0;
    for (let i = 0; i < binds.length; i++) {
        const b = binds[i];
        try {
            const ok = !!b.fn();
            const comp = $c.util.getComponent(b.id);
            if (comp && comp.setStyle) { comp.setStyle("display", ok ? "" : "none"); }
            else if (comp) { if (ok) { if (comp.show) { comp.show(); } } else if (comp.hide) { comp.hide(); } }
            if (ok && b.grids) {
                for (let gi = 0; gi < b.grids.length; gi++) {
                    const gc = $c.util.getComponent(b.grids[gi]);
                    if (gc && gc.refreshGridView) { gc.refreshGridView(); }
                }
            }
            applied++;
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); }
    }
    return applied;
};

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.initValue();
        scwin.chkChrgDesignReadonly();
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil25112.onpageload' }); }
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_attrReals();
        await scwin.init_conds();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil25112.onpageload' });
    }
};


