/**
 * @method
 * @name scwin.tx_fn_Modify
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_Modify = async function () {
    const sbmOptions = {
        id: "tx_fn_Modify",
        method: "post",
        action: "/account/corpDiscls.do",
        ref: "dma_ModifyReq",
